INSERT INTO outbox_event (
    event_id, aggregate_id, event_type, payload, status, publish_attempts, next_retry_at, created_at
) VALUES (
    #{eventId}, #{aggregateId}, #{eventType}, CAST(#{payload} AS JSON), 'PENDING', 0, #{nextRetryAt}, #{createdAt}
