mapper.select:
SELECT id, event_id, aggregate_id, event_type, CAST(payload AS CHAR) AS payload, status,
       publish_attempts, next_retry_at, published_at, created_at, last_error
FROM outbox_event
WHERE status = 'PENDING' AND next_retry_at <= #{now}
ORDER BY id LIMIT #{limit}

mapper.update:
UPDATE outbox_event SET publish_attempts = publish_attempts + 1, next_retry_at = #{nextRetryAt},
    last_error = #{lastError}
WHERE id = #{id} AND status = 'PENDING'
